ref_dt = frappe.form_dict.get("reference_doctype")
ref_nm = frappe.form_dict.get("reference_name")
FIELDS = ["name", "reference_doctype", "reference_name", "document_type", "document_number",
          "attachment", "status", "expiry", "uploaded_by", "upload_date", "current_version", "remarks"]
related = []
if ref_dt == "Customer":
    for q in frappe.get_all("Quotation", filters={"quotation_to": "Customer", "party_name": ref_nm}, pluck="name"):
        related.append(("Quotation", q))
    for o in frappe.get_all("Opportunity", filters={"opportunity_from": "Customer", "party_name": ref_nm}, pluck="name"):
        related.append(("Opportunity", o))
    for fd in frappe.get_all("Finance Dossier", filters={"finance_dossier_from": "Customer", "id": ref_nm}, pluck="name"):
        related.append(("Finance Dossier", fd))
    lead = frappe.db.get_value("Customer", ref_nm, "lead_name")
    if lead:
        related.append(("Lead", lead))
elif ref_dt == "Lead":
    for o in frappe.get_all("Opportunity", filters={"opportunity_from": "Lead", "party_name": ref_nm}, pluck="name"):
        related.append(("Opportunity", o))
    for q in frappe.get_all("Quotation", filters={"quotation_to": "Lead", "party_name": ref_nm}, pluck="name"):
        related.append(("Quotation", q))
    for fd in frappe.get_all("Finance Dossier", filters={"finance_dossier_from": "Lead", "id": ref_nm}, pluck="name"):
        related.append(("Finance Dossier", fd))
    for c in frappe.get_all("Customer", filters={"lead_name": ref_nm}, pluck="name"):
        related.append(("Customer", c))
elif ref_dt == "Opportunity":
    for q in frappe.get_all("Quotation", filters={"custom_opportunity_from": ref_nm}, pluck="name"):
        related.append(("Quotation", q))
    for qi in frappe.get_all("Quotation Item", filters={"prevdoc_docname": ref_nm, "prevdoc_doctype": "Opportunity"}, fields=["parent"]):
        related.append(("Quotation", qi.parent))
    for fd in frappe.get_all("Finance Dossier", filters={"finance_dossier_from": "Opportunity", "id": ref_nm}, pluck="name"):
        related.append(("Finance Dossier", fd))
    opp = frappe.db.get_value("Opportunity", ref_nm, ["opportunity_from", "party_name"], as_dict=True)
    if opp and opp.opportunity_from and opp.party_name:
        related.append((opp.opportunity_from, opp.party_name))
elif ref_dt == "Quotation":
    q = frappe.db.get_value("Quotation", ref_nm, ["quotation_to", "party_name", "custom_opportunity_from"], as_dict=True)
    if q and q.quotation_to and q.party_name:
        related.append((q.quotation_to, q.party_name))
    if q and q.custom_opportunity_from:
        related.append(("Opportunity", q.custom_opportunity_from))
    for qi in frappe.get_all("Quotation Item", filters={"parent": ref_nm, "prevdoc_doctype": "Opportunity"}, fields=["prevdoc_docname"]):
        if qi.prevdoc_docname:
            related.append(("Opportunity", qi.prevdoc_docname))
elif ref_dt == "Finance Dossier":
    fd = frappe.db.get_value("Finance Dossier", ref_nm, ["finance_dossier_from", "id"], as_dict=True)
    if fd and fd.finance_dossier_from and fd.id:
        related.append((fd.finance_dossier_from, fd.id))
        # walk the deal chain so the FD can review documents uploaded on the
        # Quotation's Opportunity (and the underlying Lead/Customer) too.
        if fd.finance_dossier_from == "Quotation":
            q = frappe.db.get_value("Quotation", fd.id,
                ["quotation_to", "party_name", "custom_opportunity_from", "opportunity"], as_dict=True)
            if q:
                opp = q.custom_opportunity_from or q.opportunity
                if opp:
                    related.append(("Opportunity", opp))
                if q.quotation_to and q.party_name:
                    related.append((q.quotation_to, q.party_name))
seen = set(); uniq = []
for d, n in related:
    if (d, n) == (ref_dt, ref_nm) or (d, n) in seen:
        continue
    seen.add((d, n)); uniq.append((d, n))
own = frappe.get_all("Business Documentation", filters={"reference_doctype": ref_dt, "reference_name": ref_nm}, fields=FIELDS, order_by="document_type asc")
linked = []
for d, n in uniq:
    linked += frappe.get_all("Business Documentation", filters={"reference_doctype": d, "reference_name": n}, fields=FIELDS, order_by="document_type asc")
frappe.response["message"] = {"own": own, "linked": linked}
